const allData = $input.all();

// Verificamos si hay datos reales. 
// Si el primer item no tiene 'idcliente', asumimos que la consulta vino vacía.
const tieneDatos = allData.length > 0 && allData[0].json.idcliente !== undefined;

let htmlContent = "";

if (tieneDatos) {
  htmlContent = `
  <p style="font-family: Arial, sans-serif; font-size: 14px; color: #333;">
    Buen día compañeros,<br><br>
    Se adjuntan los usuarios que requieren validación:
  </p>
  <table border="1" style="border-collapse: collapse; width: 100%; font-family: Arial, sans-serif; font-size: 12px;">
    <thead>
      <tr style="background-color: #f2f2f2; text-align: left;">
        <th style="padding: 8px; border: 1px solid #ddd;">ID</th>
        <th style="padding: 8px; border: 1px solid #ddd;">ID Cliente</th>
        <th style="padding: 8px; border: 1px solid #ddd;">Nombre Cliente</th>
        <th style="padding: 8px; border: 1px solid #ddd;">ID Contacto</th>
        <th style="padding: 8px; border: 1px solid #ddd;">Nombre Usuario</th>
        <th style="padding: 8px; border: 1px solid #ddd;">Correo</th>
        <th style="padding: 8px; border: 1px solid #ddd;">Identificación</th>
        <th style="padding: 8px; border: 1px solid #ddd;">Fecha Alta</th>
      </tr>
    </thead>
    <tbody>`;

  for (const item of allData) {
    const row = item.json;
    htmlContent += `
      <tr>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.id || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.idcliente || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.nombrecliente || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.idcontacto || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.nombreusuario || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.correoContacto || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.noidentificacion || ''}</td>
        <td style="padding: 6px; border: 1px solid #ddd;">${row.fecha_alta || ''}</td>
      </tr>`;
  }

  htmlContent += `</tbody></table>
  <p style="font-family: Arial, sans-serif; font-size: 12px; color: #777; margin-top: 20px;">
    Este es un mensaje automático generado por el sistema de monitoreo.
  </p>`;
}

return {
  hay_datos: tieneDatos,
  tabla_html: htmlContent
};
